<script setup>import{Link}from'@inertiajs/vue3';import{computed}from'vue';const p=defineProps({href:String,variant:{type:String,default:'primary'},loading:Boolean,disabled:Boolean,type:{type:String,default:'button'}});const cls=computed(()=>`btn-${{secondary:'secondary',danger:'danger',ghost:'ghost'}[p.variant]||'primary'}`)</script><template><Link v-if="href" :href="href" :class="cls" :aria-disabled="disabled||loading"><span v-if="loading" class="lp-spinner" aria-hidden="true"></span><slot/></Link><button v-else :type="type" :class="cls" :disabled="disabled||loading"><span v-if="loading" class="lp-spinner" aria-hidden="true"></span><slot/></button></template>
